<!DOCTYPE html><html lang="{{ str_replace('_', '-', app()->getLocale()) }}"><head>    <meta charset="utf-8">    <meta name="viewport" content="width=device-width, initial-scale=1">    <meta name="theme-color" content="#29131f">    <meta name="robots" content="noindex, nofollow">    <meta name="description" content="BeautyPro HQ is preparing a better way to discover, book, and grow beauty services. Join the waitlist for launch updates.">    <title>Coming Soon | BeautyPro HQ</title>    <link rel="icon" href="/favicon.svg" type="image/svg+xml">    <style>        @font-face{font-family:Inter;font-style:normal;font-weight:400 900;font-display:swap;src:url('https://fonts.gstatic.com/s/inter/v20/UcC73FwrK3iLTeHuS_nVMrMxCp50SjIa1ZL7W0Q5nw.woff2') format('woff2')}        @font-face{font-family:'Playfair Display';font-style:normal;font-weight:400 900;font-display:swap;src:url('https://fonts.gstatic.com/s/playfairdisplay/v40/nuFiD-vYSZviVYUb_rj3ij__anPXDTzYgEM86xQ.woff2') format('woff2')}        *{box-sizing:border-box}html{min-height:100%;background:#fdfbf8;color:#29131f;font-family:Inter,'Avenir Next','Segoe UI',system-ui,sans-serif}body{min-height:100vh;margin:0;overflow-x:hidden}        .page{position:relative;isolation:isolate;min-height:100vh;background:linear-gradient(135deg,rgba(253,251,248,.96),rgba(250,245,239,.9)),url('https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=1800&q=76') center/cover fixed}        .page:before{display:none}        .glow{position:fixed;inset:auto auto 0 0;z-index:-1;width:22rem;height:22rem;border-radius:999px;background:rgba(201,54,97,.22);filter:blur(70px);transform:translate(var(--x,18vw),var(--y,18vh));transition:transform .2s ease;pointer-events:none}        .wrap{display:flex;min-height:100vh;width:min(1040px,calc(100% - 32px));margin:0 auto;padding:12px 0 12px;flex-direction:column}        header{display:flex;align-items:center;justify-content:center}.brand{display:inline-flex;flex-direction:column;align-items:center;line-height:1;color:#26211e;text-decoration:none}.brand-bphq{font-family:'Playfair Display',Georgia,serif;font-size:2.15rem;font-weight:400;letter-spacing:-.08em}.brand-name{margin-top:4px;color:#78716c;font-size:10px;font-weight:900;letter-spacing:.42em}        main{position:relative;display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,.62fr);gap:28px;align-items:center;flex:1;padding:58px 0 12px;overflow:hidden}        .image-marquees{grid-column:1/-1;order:3;position:relative;z-index:0;display:grid;width:100%;gap:14px;overflow:hidden;padding:2px 0;pointer-events:none}.image-row{display:flex;width:max-content;gap:14px;animation:image-marquee-left 34s linear infinite}.image-row.reverse{animation-name:image-marquee-right}.image-row img{width:156px;height:88px;border:1px solid rgba(255,255,255,.86);border-radius:10px;object-fit:cover;box-shadow:0 14px 35px rgba(41,19,31,.16)}        .copy,.panel{position:relative;z-index:1}.copy{order:1}.panel{order:2}        .copy{position:relative;padding-left:18px}.copy:before{content:"";position:absolute;left:0;top:.35rem;width:3px;height:calc(100% - .7rem);border-radius:999px;background:linear-gradient(#54213f,#c93661,#15816f)}        h1{max-width:650px;margin:0;color:#29131f;font-family:'Playfair Display',Georgia,serif;font-size:clamp(44px,6.7vw,78px);font-weight:400;line-height:.94;letter-spacing:0}.lead{max-width:560px;margin:16px 0 0;color:#51443e;font-size:clamp(15px,1.55vw,18px);line-height:1.48}        .panel{position:relative;overflow:hidden;border:1px solid rgba(80,44,66,.16);border-radius:10px;background:linear-gradient(145deg,rgba(255,255,255,.93),rgba(253,251,248,.82));box-shadow:0 24px 70px rgba(41,19,31,.16);backdrop-filter:blur(20px);padding:17px;transform:perspective(900px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transition:transform .16s ease}.panel:before{content:"";position:absolute;inset:0 0 auto;height:3px;background:linear-gradient(90deg,#54213f,#c93661,#15816f);background-size:200% 100%;animation:sweep 3.5s linear infinite}.panel h2{margin:0;color:#29131f;font-family:'Playfair Display',Georgia,serif;font-size:25px;font-weight:400;line-height:1.05}.panel p{margin:6px 0 0;color:#6b5b53;font-size:14px;line-height:1.38}        form{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:13px}.field{grid-column:1/-1}label{display:block;margin-bottom:6px;color:#502c42;font-size:12px;font-weight:850}input{width:100%;border:1px solid #dfc8d9;border-radius:8px;background:white;padding:11px 12px;color:#29131f;font:inherit;outline:none;transition:.16s ease}input:focus{border-color:#c93661;box-shadow:0 0 0 4px rgba(201,54,97,.13)}        button{min-height:42px;border:0;border-radius:8px;background:#54213f;color:white;font:inherit;font-weight:900;padding:0 16px;cursor:pointer;transition:transform .18s ease,background .18s ease,box-shadow .18s ease}button:hover{background:#aa294f;box-shadow:0 12px 28px rgba(170,41,79,.22);transform:translateY(-1px)}button:disabled{cursor:wait;opacity:.7;transform:none}        .message{grid-column:1/-1;display:none;border-radius:8px;padding:10px 11px;font-size:13px;line-height:1.38}.message.show{display:block}.message.ok{background:#ecfdf3;color:#027a48}.message.err{background:#fff1f3;color:#c01048}        .marquee{width:100%;overflow:hidden;border-block:1px solid rgba(80,44,66,.12);padding:7px 0;color:#60334f;font-size:10px;font-weight:900;letter-spacing:.14em;text-transform:uppercase;white-space:nowrap}.track{display:inline-flex;gap:24px;min-width:max-content;animation:marquee 25s linear infinite}.track span{display:inline-flex;align-items:center;gap:24px}.track span:after{content:"";width:4px;height:4px;border-radius:999px;background:#c93661}        footer{display:flex;flex-wrap:wrap;justify-content:center;gap:12px;padding-top:8px;color:#78716c;font-size:12px}.links{display:flex;gap:12px}.links a{color:#502c42;text-decoration:none;font-weight:850}        @keyframes sweep{to{background-position:200% 0}}@keyframes marquee{to{transform:translateX(-50%)}}@keyframes image-marquee-left{to{transform:translateX(-50%)}}@keyframes image-marquee-right{from{transform:translateX(-50%)}to{transform:translateX(0)}}        @media (max-width:820px){.page{background-attachment:scroll}main{grid-template-columns:1fr;gap:18px;padding:24px 0 12px}.panel{max-width:560px}}        @media (max-width:820px){.image-marquees{position:relative;inset:auto;order:2;margin:-2px -16px 0;gap:10px}.copy{order:1}.panel{order:3}.image-row{gap:10px;animation-duration:30s}.image-row img{width:132px;height:78px}}        @media (max-width:560px){.wrap{width:min(100% - 20px,1040px);padding:10px 0 8px}.brand-bphq{font-size:1.55rem}.brand-name{font-size:7px;letter-spacing:.3em}main{display:flex;flex-direction:column;gap:12px;padding:34px 0 8px}.image-marquees{width:calc(100% + 20px);margin:0 -10px;gap:8px}.image-row{gap:8px;animation-duration:26s}.image-row img{width:116px;height:72px;border-radius:8px}.copy{padding-left:12px}.copy:before{width:2px}h1{font-size:34px;line-height:.98}.lead{margin-top:9px;font-size:14px;line-height:1.34}.panel{width:100%;padding:13px}.panel h2{font-size:22px}.panel p{font-size:13px;line-height:1.3}form{grid-template-columns:1fr;gap:8px;margin-top:10px}button{width:100%;min-height:40px}.marquee{padding:6px 0;font-size:9px;letter-spacing:.1em}footer{padding-top:8px;font-size:11px}}        @media (max-height:700px) and (max-width:560px){.lead,.marquee,footer{display:none}.panel p{display:none}main{padding:8px 0 6px}}        @media (prefers-reduced-motion:reduce){.panel:before,.track,.image-row{animation:none}.panel{transform:none!important}.glow{display:none}}    </style></head><body>    <div class="page">        <div class="glow" aria-hidden="true"></div>        <div class="wrap">            <header>                <a class="brand" href="/" aria-label="BeautyPro HQ">                    <span class="brand-bphq">BPHQ</span>                    <span class="brand-name">BEAUTYPROHQ</span>                </a>            </header>            <main>                <div class="image-marquees" aria-hidden="true">                    <div class="image-row">                        <img alt="" src="https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1516975080664-ed2fc6a32937?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1595476108010-b4d1f102b1b1?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1516975080664-ed2fc6a32937?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1512496015851-a90fb38ba796?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1595476108010-b4d1f102b1b1?auto=format&fit=crop&w=260&q=68">                    </div>                    <div class="image-row reverse">                        <img alt="" src="https://images.unsplash.com/photo-1580618672591-eb180b1a973f?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1487412947147-5cebf100ffc2?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1503951914875-452162b0f3f1?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1562322140-8baeececf3df?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1580618672591-eb180b1a973f?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1487412947147-5cebf100ffc2?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1596462502278-27bfdc403348?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1503951914875-452162b0f3f1?auto=format&fit=crop&w=260&q=68">                        <img alt="" src="https://images.unsplash.com/photo-1562322140-8baeececf3df?auto=format&fit=crop&w=260&q=68">                    </div>                </div>                <section class="copy">                    <h1>Your beauty service ecosystem is almost here.</h1>                    <p class="lead">BeautyPro HQ is preparing trusted discovery, seamless bookings, industry updates, and business tools for beauty professionals.</p>                </section>                <aside class="panel" id="waitlist-panel" aria-label="Join the launch waitlist">                    <h2>Get launch access</h2>                    <p>Join the first list for customer, provider, partner, and event updates.</p>                    <form id="waitlist-form">                        <div class="field">                            <label for="email">Email address</label>                            <input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required>                        </div>                        <button id="submit-button" type="submit">Notify me</button>                        <div id="form-message" class="message" role="status" aria-live="polite"></div>                    </form>                </aside>            </main>            <div class="marquee" aria-label="BeautyPro HQ launch areas">                <div class="track">                    <span>Beauty bookings</span><span>Trusted professionals</span><span>Provider tools</span><span>Events and opportunities</span>                    <span>Beauty bookings</span><span>Trusted professionals</span><span>Provider tools</span><span>Events and opportunities</span>                </div>            </div>            <footer>                <span>&copy; {{ date('Y') }} BeautyPro HQ. All rights reserved.</span>                <span class="links"><a href="mailto:hello@beautyprohq.com">Contact</a></span>            </footer>        </div>    </div>    <script>        const form = document.getElementById('waitlist-form');        const button = document.getElementById('submit-button');        const message = document.getElementById('form-message');        const panel = document.getElementById('waitlist-panel');        const glow = document.querySelector('.glow');        window.addEventListener('pointermove', (event) => {            glow?.style.setProperty('--x', `${event.clientX - 170}px`);            glow?.style.setProperty('--y', `${event.clientY - 170}px`);            if (!panel || window.matchMedia('(max-width: 820px)').matches) return;            const rect = panel.getBoundingClientRect();            const x = (event.clientX - rect.left) / rect.width - .5;            const y = (event.clientY - rect.top) / rect.height - .5;            panel.style.setProperty('--ry', `${x * 5}deg`);            panel.style.setProperty('--rx', `${y * -5}deg`);        });        panel?.addEventListener('pointerleave', () => {            panel.style.setProperty('--rx', '0deg');            panel.style.setProperty('--ry', '0deg');        });        form.addEventListener('submit', async (event) => {            event.preventDefault();            button.disabled = true;            button.textContent = 'Joining...';            message.className = 'message';            message.textContent = '';            try {                const response = await fetch('/api/newsletter/subscribe', {                    method: 'POST',                    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },                    body: JSON.stringify({ email: form.email.value }),                });                const data = await response.json().catch(() => ({}));                if (!response.ok) throw new Error(data.message || 'Please check the email address and try again.');                form.reset();                message.textContent = data.message || 'You are on the list. We will send launch updates soon.';                message.className = 'message ok show';            } catch (error) {                message.textContent = error.message || 'Something went wrong. Please try again.';                message.className = 'message err show';            } finally {                button.disabled = false;                button.textContent = 'Notify me';            }        });    </script></body></html>